76: function readJson(path: string): JsonRecord {
77:   const parsed = JSON.parse(readFileSync(path, 'utf8')) as unknown;
78:   if (!isRecord(parsed)) {
79:     throw new TypeError(`${path} must contain a JSON object.`);
80:   }
81:   return parsed;
