84: function readJsonl(path: string): JsonRecord[] {
85:   if (!existsSync(path)) return [];
86:   return readFileSync(path, 'utf8')
87:     .split(/\r?\n/u)
88:     .map((line) => line.trim())
89:     .filter(Boolean)
90:     .map((line, index) => {
91:       try {
92:         const parsed = JSON.parse(line) as unknown;
93:         if (!isRecord(parsed)) throw new TypeError('record must be a JSON object');
94:         return parsed;
95:       } catch (error) {
96:         const message = error instanceof Error ? error.message : String(error);
97:         throw new Error(`Invalid JSONL at ${path}:${index + 1}: ${message}`);
98:       }
99:     });
100: }
