102: function extractSection(markdown: string, heading: string): string {
103:   const escaped = heading.replace(/[.*+?^${}()|[\]\\]/gu, '\\$&');
104:   const match = markdown.match(new RegExp(
105:     `^##[ \\t]+${escaped}[ \\t]*\\r?\\n([\\s\\S]*?)(?=^##[ \\t]+|(?![\\s\\S]))`,
106:     'mu',
107:   ));
108:   return match?.[1]?.trim() ?? '';
