111: function extractListText(section: string): string[] {
112:   return section
113:     .split(/\r?\n/u)
114:     .map((line) => normalizeText(line.replace(/^[-*]\s+(?:\[[ xX]\]\s*)?/u, '')))
115:     .filter((line) => line !== '' && !line.startsWith('['));
116: }
