124: function candidateFromSeed(seed: CandidateSeed, boundaryRationale: string): PivotCandidate {
125:   const digest = fingerprint(seed.title, seed.focus);
126:   return {
127:     id: `research-${seed.source}-${digest.slice(0, 12)}`,
128:     title: seed.title,
129:     focus: seed.focus,
130:     evidenceRefs: [seed.evidenceRef],
131:     relevanceRationale: seed.relevanceRationale,
132:     boundaryVerdict: {
133:       status: 'within_boundary',
134:       rationale: boundaryRationale,
135:     },
136:     fingerprint: digest,
137:     seatProvenance: [`research-state:${seed.source}`],
138:   };
139: }
