141: function priorCandidate(text: string, source: string, evidenceRef: string): PivotCandidate | null {
142:   const focus = normalizeText(text);
143:   if (!focus) return null;
144:   return candidateFromSeed({
145:     source,
146:     title: focus,
147:     focus,
148:     evidenceRef,
149:     relevanceRationale: 'This direction is already current, saturated, rejected, or previously selected.',
150:   }, 'Prior-state entry retained only for deduplication inside the existing research boundary.');
151: }
