153: function readText(value: unknown): string {
154:   if (typeof value === 'string') return normalizeText(value);
155:   if (!isRecord(value)) return '';
156:   for (const field of ['text', 'focus', 'title', 'question', 'direction', 'pattern', 'message']) {
157:     const text = normalizeText(value[field]);
158:     if (text) return text;
159:   }
160:   return '';
161: }
162: 
163: function readStringList(value: unknown): string[] {
164:   return Array.isArray(value) ? value.map(readText).filter(Boolean) : [];
165: }
