167: function readPivotEvents(artifactRoot: string): JsonRecord[] {
168:   const pivotsRoot = join(artifactRoot, 'divergent', 'pivots');
169:   if (!existsSync(pivotsRoot)) return [];
170:   return readdirSync(pivotsRoot, { withFileTypes: true })
171:     .filter((entry) => entry.isDirectory())
172:     .sort((left, right) => left.name.localeCompare(right.name))
173:     .flatMap((entry) => readJsonl(join(pivotsRoot, entry.name, 'council', 'state.jsonl')));
174: }
