198: function buildCandidateSeeds(
199:   registry: JsonRecord,
200:   stateRecords: readonly JsonRecord[],
201: ): CandidateSeed[] {
202:   const seeds: CandidateSeed[] = [];
203:   const add = (seed: CandidateSeed): void => {
204:     if (normalizeText(seed.focus) && normalizeText(seed.evidenceRef)) seeds.push(seed);
205:   };
206: 
207:   for (const [index, question] of [
208:     ...(Array.isArray(registry.openQuestions) ? registry.openQuestions : []),
209:     ...(Array.isArray(registry.carriedForwardOpenQuestions) ? registry.carriedForwardOpenQuestions : []),
210:   ].entries()) {
211:     const text = readText(question);
212:     if (!text) continue;
213:     add({
214:       source: 'adjacent-question',
215:       title: `Investigate adjacent question: ${text}`,
216:       focus: text,
217:       evidenceRef: `findings-registry.json#open-question-${index + 1}`,
218:       relevanceRationale: 'The canonical research registry still carries this question inside the current topic.',
219:     });
220:   }
221: 
222:   const questionConflicts = Array.isArray(registry.questionConflicts) ? registry.questionConflicts : [];
223:   questionConflicts.forEach((conflict, index) => {
224:     if (!isRecord(conflict)) return;
225:     const inboxValue = normalizeText(conflict.inboxValue);
226:     const registryValue = normalizeText(conflict.registryValue);
227:     if (!inboxValue || !registryValue) return;
228:     add({
229:       source: 'contradiction-gap',
230:       title: `Resolve conflicting research question ${index + 1}`,
231:       focus: `Verify whether "${inboxValue}" or "${registryValue}" is supported by the current evidence.`,
232:       evidenceRef: `findings-registry.json#question-conflict-${index + 1}`,
233:       relevanceRationale: 'The reducer recorded an unresolved contradiction in canonical question state.',
234:     });
235:   });
236: 
237:   stateRecords.forEach((record, recordIndex) => {
238:     const evidenceRef = `deep-research-state.jsonl#record-${recordIndex + 1}`;
239:     for (const [field, source, titlePrefix, rationale] of [
240:       ['verificationGaps', 'verification-gap', 'Verify recorded gap', 'The iteration history explicitly records an unresolved verification gap.'],
241:       ['contradictions', 'contradiction-gap', 'Resolve recorded contradiction', 'The iteration history explicitly records contradictory evidence.'],
242:       ['missingSourceClasses', 'missing-source-class', 'Add missing source class', 'The iteration history explicitly identifies an unrepresented source class.'],
243:       ['alternateEvidenceMethods', 'alternate-evidence', 'Apply alternate evidence method', 'The iteration history explicitly identifies an unused evidence method.'],
244:       ['unansweredAdjacentQuestions', 'adjacent-question', 'Investigate adjacent question', 'The iteration history explicitly carries an unanswered adjacent question.'],
245:     ] as const) {
246:       readStringList(record[field]).forEach((text) => add({
247:         source,
248:         title: `${titlePrefix}: ${text}`,
249:         focus: text,
250:         evidenceRef,
251:         relevanceRationale: rationale,
252:       }));
253:     }
254: 
255:     if (Array.isArray(record.graphEvents)) {
256:       record.graphEvents.forEach((event, eventIndex) => {
257:         if (!isRecord(event) || normalizeText(event.relation).toUpperCase() !== 'CONTRADICTS') return;
258:         const sourceId = normalizeText(event.source);
259:         const targetId = normalizeText(event.target);
260:         if (!sourceId || !targetId) return;
261:         add({
262:           source: 'contradiction-gap',
263:           title: `Verify contradiction ${sourceId} -> ${targetId}`,
264:           focus: `Resolve the recorded contradiction between ${sourceId} and ${targetId} using independent evidence.`,
265:           evidenceRef: `${evidenceRef}:graph-event-${eventIndex + 1}`,
266:           relevanceRationale: 'The current coverage graph records this contradiction inside the active research topic.',
267:         });
268:       });
269:     }
270:   });
271: 
272:   const findings = Array.isArray(registry.keyFindings) ? registry.keyFindings : [];
273:   findings.slice(-3).forEach((finding, index) => {
274:     const text = readText(finding);
275:     if (!text) return;
276:     add({
277:       source: 'alternate-evidence',
278:       title: `Independently verify finding: ${text}`,
279:       focus: `Cross-check the finding "${text}" with an evidence method not used by its recorded support.`,
280:       evidenceRef: `findings-registry.json#key-finding-${Math.max(1, findings.length - 2 + index)}`,
281:       relevanceRationale: 'The direction tests an existing in-scope finding rather than widening the research topic.',
282:     });
283:   });
284: 
285:   return seeds;
286: }
