292: /** Render the exact parseable result contract for one native research Council seat. */
293: export function renderResearchPivotSeatPrompt(
294:   seat: PivotSeatMandate,
295:   dispatchContext: {
296:     readonly candidates: readonly PivotCandidate[];
297:     readonly previousFocus: string;
298:     readonly normalizedTrigger: string;
299:   },
300: ): string {
301:   return [
302:     'You are one native research direction-selection Council seat. Do not dispatch sub-agents, write files, or widen the research charter.',
303:     '',
304:     `Seat id: ${seat.id}`,
305:     `Mandate: ${seat.mandate}`,
306:     `Saturation trigger: ${dispatchContext.normalizedTrigger}`,
307:     `Previous focus: ${dispatchContext.previousFocus}`,
308:     '',
309:     'Candidate frontier:',
310:     JSON.stringify(dispatchContext.candidates, null, 2),
311:     '',
312:     'Return exactly one parseable JSON object and no surrounding prose or markdown:',
313:     '{"seatId":"' + seat.id + '","selectedCandidateId":null,"materialEndorsement":false,"rationale":"<non-empty rationale>","blockers":[]}',
314:     'Replace selectedCandidateId with one candidate id string and set materialEndorsement to true only for a material endorsement. Blockers may contain {severity, message, candidateId?}.',
315:   ].join('\n');
316: }
