318: // ───────────────────────────────────────────────────────────────────
319: // 5. ADAPTER INPUT
320: // ───────────────────────────────────────────────────────────────────
321: 
322: /** Derive bounded candidates, prior directions, usage, identity, and mandates from research state. */
323: export function buildResearchPivotPreparationInput(
324:   options: BuildResearchPivotInputOptions,
325: ): ResearchPivotPreparationInput {
326:   if (!Number.isInteger(options.currentIteration) || options.currentIteration < 0) {
327:     throw new TypeError('currentIteration must be a non-negative integer.');
328:   }
329:   if (!Number.isInteger(options.maxIterations) || options.maxIterations < 1) {
330:     throw new TypeError('maxIterations must be a positive integer.');
331:   }
332:   const config = readJson(options.configPath);
333:   const legacyRegistryPath = join(dirname(options.registryPath), 'deep-research-findings-registry.json');
334:   const registry = readJson(existsSync(options.registryPath) ? options.registryPath : legacyRegistryPath);
335:   const strategy = readFileSync(options.strategyPath, 'utf8');
336:   const stateRecords = readJsonl(options.stateLogPath);
337:   const pivotEvents = readPivotEvents(options.artifactRoot);
338:   const lineage = isRecord(config.lineage) ? config.lineage : {};
339:   const sessionId = normalizeText(lineage.sessionId);
340:   const generation = typeof lineage.generation === 'number' || typeof lineage.generation === 'string'
341:     ? lineage.generation
342:     : 1;
343:   if (!sessionId) throw new TypeError('Research config lineage.sessionId is required for a pivot.');
344: 
345:   const latestIteration = stateRecords.filter((record) => record.type === 'iteration').at(-1);
346:   const strategyFocus = extractSection(strategy, '11. NEXT FOCUS');
347:   const previousFocus = normalizeText(strategyFocus) || normalizeText(latestIteration?.focus);
348:   if (!previousFocus) throw new TypeError('A current research focus is required for a pivot.');
349: 
350:   const topic = normalizeText(config.topic);
351:   if (!topic) throw new TypeError('Research config topic is required for boundary validation.');
352:   const nonGoals = extractListText(extractSection(strategy, '4. NON-GOALS'));
353:   const seeds = buildCandidateSeeds(registry, stateRecords);
354:   const boundaryRejections = seeds.filter((seed) => conflictsWithNonGoal(seed, nonGoals));
355:   const acceptedSeeds = seeds.filter((seed) => !conflictsWithNonGoal(seed, nonGoals));
356:   const boundaryRationale = nonGoals.length > 0
357:     ? `Derived from canonical state for topic "${topic}" and checked against ${nonGoals.length} explicit non-goal(s).`
358:     : `Derived from canonical state for topic "${topic}"; no populated non-goal excluded this direction.`;
359:   const candidates = uniqueCandidates(acceptedSeeds.map((seed) => candidateFromSeed(seed, boundaryRationale)));
360: 
361:   const completedEvents = pivotEvents.filter((event) => event.event === 'pivot_completed');
362:   const selectedEvents = pivotEvents.filter((event) => event.event === 'pivot_selected');
363:   const rejectedEvents = pivotEvents.filter((event) => event.event === 'pivot_candidate_rejected');
364:   const saturatedDirections = [...new Set([
365:     ...completedEvents.flatMap((event) => readStringList(event.saturatedDirections)),
366:     ...completedEvents.map((event) => normalizeText(event.previousFocus)).filter(Boolean),
367:     previousFocus,
368:   ])];
369: 
370:   const priorCandidates: PivotCandidate[] = [];
371:   const addPriorText = (value: unknown, source: string, evidenceRef: string): void => {
372:     const candidate = priorCandidate(readText(value), source, evidenceRef);
373:     if (candidate) priorCandidates.push(candidate);
374:   };
375:   addPriorText(previousFocus, 'current-focus', 'deep-research-strategy.md#next-focus');
376:   saturatedDirections.forEach((direction, index) => addPriorText(
377:     direction,
378:     'saturated-direction',
379:     `divergent/pivots#saturated-${index + 1}`,
380:   ));
381:   (Array.isArray(registry.ruledOutDirections) ? registry.ruledOutDirections : []).forEach((entry, index) => addPriorText(
382:     entry,
383:     'ruled-out-direction',
384:     `findings-registry.json#ruled-out-${index + 1}`,
385:   ));
386:   (Array.isArray(registry.rejectedPatterns) ? registry.rejectedPatterns : []).forEach((entry, index) => addPriorText(
387:     entry,
388:     'rejected-pattern',
389:     `findings-registry.json#rejected-pattern-${index + 1}`,
390:   ));
391:   selectedEvents.forEach((event, index) => {
392:     if (isRecord(event.selectedCandidate)) {
393:       priorCandidates.push(event.selectedCandidate as unknown as PivotCandidate);
394:     } else {
395:       addPriorText(event.selectedCandidate, 'selected-direction', `divergent/pivots#selected-${index + 1}`);
396:     }
397:   });
398:   rejectedEvents.forEach((event, index) => addPriorText(
399:     event.candidate,
400:     'adapter-rejected-direction',
401:     `divergent/pivots#candidate-rejected-${index + 1}`,
402:   ));
403: 
404:   const seats: readonly PivotSeatMandate[] = [
405:     {
406:       id: 'seat-001',
407:       mandate: 'Analytical: select the direction that closes the most consequential unanswered evidence gap while remaining inside the research charter.',
408:     },
409:     {
410:       id: 'seat-002',
411:       mandate: 'Critical: challenge candidate relevance, boundary safety, contradiction handling, and risk of re-entering saturated directions.',
412:     },
413:     {
414:       id: 'seat-003',
415:       mandate: 'Pragmatic: select the most evidence-efficient next direction that can produce material information within the remaining iterations.',
416:     },
417:   ];
418:   const usage: PivotUsage = {
419:     completedPivots: completedEvents.length,
420:     councilSeatOutputs: pivotEvents.filter((event) => event.event === 'pivot_seat_returned').length,
421:     remainingIterations: Math.max(0, options.maxIterations - options.currentIteration),
422:   };
423: 
424:   return {
425:     artifactRoot: options.artifactRoot,
426:     identity: {
427:       sessionId,
428:       generation,
429:       loopType: 'research',
430:       sourceIteration: options.currentIteration,
431:       normalizedTrigger: `research saturation: ${options.triggerReason}`,
432:       ordinal: usage.completedPivots + 1,
433:     },
434:     config: config as unknown as PivotConfigInput,
435:     usage,
436:     seats,
437:     candidates,
438:     priorCandidates: uniqueCandidates(priorCandidates),
439:     previousFocus,
440:     saturatedDirections,
441:     boundaryRejections,
442:   };
443: }

