225:   const searchDebt = Array.isArray(registry.searchDebt) ? registry.searchDebt : [];
226:   searchDebt.filter(isRecord).forEach((entry, index) => {
227:     const refs = readStringList(entry.targetRefs).concat(readStringList(entry.evidenceRefs));
