295: /** Render the parseable result contract and read-only boundary for one native review seat. */
296: export function renderReviewPivotSeatPrompt(
297:   seat: PivotSeatMandate,
298:   dispatchContext: {
299:     readonly candidates: readonly PivotCandidate[];
300:     readonly previousFocus: string;
301:     readonly normalizedTrigger: string;
302:   },
303: ): string {
304:   return [
305:     'You are one native review direction-selection Council seat. Do not dispatch sub-agents or write files.',
306:     'Review target is READ-ONLY. Do not modify reviewed files.',
