311:     `Mandate: ${seat.mandate}`,
312:     `Saturation trigger: ${dispatchContext.normalizedTrigger}`,
313:     `Previous focus: ${dispatchContext.previousFocus}`,
314:     '',
315:     'Candidate frontier:',
