328: /** Derive bounded candidates, prior directions, usage, identity, and mandates from review state. */
329: export function buildReviewPivotPreparationInput(
330:   options: BuildReviewPivotInputOptions,
331: ): ReviewPivotPreparationInput {
332:   if (!Number.isInteger(options.currentIteration) || options.currentIteration < 0) {
333:     throw new TypeError('currentIteration must be a non-negative integer.');
334:   }
335:   if (!Number.isInteger(options.maxIterations) || options.maxIterations < 1) {
336:     throw new TypeError('maxIterations must be a positive integer.');
337:   }
338:   if (options.triggerReason !== 'all_dimensions_clean') {
339:     throw new TypeError('Review divergent pivots require the all_dimensions_clean legal-stop reason.');
340:   }
341: 
342:   const config = readJson(options.configPath);
343:   const registry = readJson(options.registryPath);
344:   const strategy = readFileSync(options.strategyPath, 'utf8');
345:   const stateRecords = readJsonl(options.stateLogPath);
346:   const pivotEvents = readPivotEvents(options.artifactRoot);
347:   const sessionId = normalizeText(config.sessionId);
348:   const generation = typeof config.generation === 'number' || typeof config.generation === 'string'
349:     ? config.generation
350:     : 1;
351:   if (!sessionId) throw new TypeError('Review config sessionId is required for a pivot.');
352:   if (!normalizeText(config.reviewTarget)) throw new TypeError('Review config reviewTarget is required for boundary validation.');
353: 
354:   const latestIteration = stateRecords.filter((record) => record.type === 'iteration').at(-1);
355:   const strategyFocus = extractSection(strategy, ['12. NEXT FOCUS', '11. NEXT FOCUS']);
356:   const previousFocus = normalizeText(strategyFocus) || normalizeText(latestIteration?.focus);
357:   if (!previousFocus) throw new TypeError('A current review dimension or direction is required for a pivot.');
358: 
359:   const seeds = buildCandidateSeeds(config, registry, stateRecords);
360:   const boundaryRejections = seeds.filter(seedViolatesReadOnlyBoundary);
361:   const candidates = uniqueCandidates(seeds.filter((seed) => !seedViolatesReadOnlyBoundary(seed)).map(candidateFromSeed));
362:   const completedEvents = pivotEvents.filter((event) => event.event === 'pivot_completed');
363:   const selectedEvents = pivotEvents.filter((event) => event.event === 'pivot_selected');
364:   const rejectedEvents = pivotEvents.filter((event) => event.event === 'pivot_candidate_rejected');
365:   const mainOverrides = stateRecords.filter((event) => event.event === 'pivot_override_accepted');
366:   const saturatedDirections = [...new Set([
367:     ...completedEvents.flatMap((event) => readStringList(event.saturatedDirections)),
368:     ...completedEvents.map((event) => normalizeText(event.previousFocus)).filter(Boolean),
369:     ...mainOverrides.flatMap((event) => readStringList(event.saturatedDirections)),
370:     previousFocus,
371:   ])];
372: 
373:   const priorCandidates: PivotCandidate[] = [];
374:   const addPrior = (value: unknown, source: string, evidenceRef: string): void => {
375:     const candidate = priorCandidate(normalizeText(value), source, evidenceRef);
376:     if (candidate) priorCandidates.push(candidate);
377:   };
378:   addPrior(previousFocus, 'current-focus', 'deep-review-strategy.md#next-focus');
379:   saturatedDirections.forEach((direction, index) => addPrior(direction, 'swept-direction', `divergent/pivots#swept-${index + 1}`));
380:   (Array.isArray(registry.ruledOutCandidates) ? registry.ruledOutCandidates : []).filter(isRecord)
381:     .forEach((entry, index) => addPrior(entry.rationale || entry.reason || entry.bugClass, 'ruled-out-direction', `deep-review-findings-registry.json#ruled-out-${index + 1}`));
382:   (Array.isArray(registry.cleanSearchProof) ? registry.cleanSearchProof : []).filter(isRecord)
383:     .forEach((entry, index) => addPrior(entry.proof || entry.rationale || entry.bugClass, 'clean-search-proof', `deep-review-findings-registry.json#clean-proof-${index + 1}`));
384:   selectedEvents.forEach((event, index) => {
385:     if (isRecord(event.selectedCandidate)) priorCandidates.push(event.selectedCandidate as unknown as PivotCandidate);
386:     else addPrior(event.selectedCandidate, 'selected-direction', `divergent/pivots#selected-${index + 1}`);
387:   });
388:   mainOverrides.forEach((event, index) => {
389:     if (isRecord(event.selectedCandidate)) priorCandidates.push(event.selectedCandidate as unknown as PivotCandidate);
390:     else addPrior(event.selectedCandidate, 'override-direction', `deep-review-state.jsonl#override-${index + 1}`);
391:   });
392:   rejectedEvents.forEach((event, index) => {
393:     const candidate = isRecord(event.candidate) ? event.candidate : null;
394:     if (candidate) priorCandidates.push(candidate as unknown as PivotCandidate);
395:     else addPrior(event.candidate, 'adapter-rejected-direction', `divergent/pivots#candidate-rejected-${index + 1}`);
396:   });
397: 
398:   const seats: readonly PivotSeatMandate[] = [
399:     { id: 'seat-001', mandate: 'Analytical: select the read-only review direction that closes the most consequential persisted coverage gap without expanding the configured target.' },
400:     { id: 'seat-002', mandate: 'Critical: challenge candidate evidence, target-boundary safety, read-only compliance, and risk of re-entering swept dimensions.' },
401:     { id: 'seat-003', mandate: 'Pragmatic: select the most evidence-efficient read-only review direction that can produce material findings within the remaining iterations.' },
402:   ];
403:   const usage: PivotUsage = {
404:     completedPivots: completedEvents.length,
405:     councilSeatOutputs: pivotEvents.filter((event) => event.event === 'pivot_seat_returned').length,
406:     remainingIterations: Math.max(0, options.maxIterations - options.currentIteration),
407:   };
408: 
409:   return {
410:     artifactRoot: options.artifactRoot,
411:     identity: {
412:       sessionId,
413:       generation,
414:       loopType: 'review',
415:       sourceIteration: options.currentIteration,
416:       normalizedTrigger: `review saturation: ${options.triggerReason}`,
417:       ordinal: usage.completedPivots + 1,
418:     },
419:     config: config as unknown as PivotConfigInput,
420:     usage,
421:     seats,
422:     candidates,
423:     priorCandidates: uniqueCandidates(priorCandidates),
424:     previousFocus,
425:     saturatedDirections,
426:     boundaryRejections,
427:   };
428: }

