77: function readJson(path: string): JsonRecord {
78:   const parsed = JSON.parse(readFileSync(path, 'utf8')) as unknown;
79:   if (!isRecord(parsed)) throw new TypeError(`${path} must contain a JSON object.`);
80:   return parsed;
