104:     const match = markdown.match(new RegExp(
105:       `^##[ \\t]+${escaped}[ \\t]*\\r?\\n([\\s\\S]*?)(?=^##[ \\t]+|(?![\\s\\S]))`,
106:       'mu',
107:     ));
108:     if (match?.[1]?.trim()) return match[1].trim();
109:   }
110:   return '';
111: }
