399:   const cassettePath = resolveCassettePath(cassetteId, options.cassetteDir);
400:   const result = await spawnCjs(scriptPath, argv, options);
401:   const cassette: ScriptRunCassette = {
402:     schemaVersion: CASSETTE_SCHEMA_VERSION,
403:     cassetteId,
404:     recordedAt: '<ISO_TIMESTAMP>',
405:     envelope: normalizeScriptRun(scriptPath, argv, result, options),
406:   };
407: 
408:   mkdirSync(dirname(cassettePath), { recursive: true });
409:   writeFileSync(cassettePath, `${stableJson(cassette)}\n`, 'utf8');
410: 
411:   return {
412:     cassetteId,
413:     cassettePath,
414:     cassette,
415:     result,
416:   };
417: }
