421:  */
422: export async function replayScriptRun(
423:   cassetteId: CassetteId,
424:   scriptPath: string,
425:   argv: string[] = [],
426:   options: ScriptCassetteOptions = {},
427: ): Promise<ReplayScriptRunResult> {
